def validate_main_health_contract(job,protocol,family):
    h=helpers()
    require(round_contract().read(job['main_health_protocol'],h)==protocol
        and round_contract().read(job['source_family_manifest'],h)==family,'Passed health context differs from serialized job')
    return round_contract().context(job,h)

